            long id = ((Number) client.get("id")).longValue();
            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
