            maxClientId = Math.max(maxClientId, id);
        }
        if (maxClientId > 0) {
            // Advance the identity so app-generated ids don't collide with seeded rows.
            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
        }

