1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    private final InvoiceRepository repository;
22	    private final LineItemRepository lineItemRepository;
23	    private final PaymentRepository paymentRepository;
24	    private final JdbcTemplate jdbc;
25	    private final Audit audit;
26	
27	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
28	            PaymentRepository paymentRepository, JdbcTemplate jdbc, Audit audit) {
29	        this.repository = repository;
30	        this.lineItemRepository = lineItemRepository;
31	        this.paymentRepository = paymentRepository;
32	        this.jdbc = jdbc;
33	        this.audit = audit;
34	    }
35	
36	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
37	    @Transactional(readOnly = true)
38	    public List<AllInvoiceView> listAll(String status) {
39	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
40	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
41	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
42	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
43	        if (status == null || status.isBlank()) {
44	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
45	        }
46	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
47	    }
48	
49	    @Transactional(readOnly = true)
50	    public List<InvoiceView> listForProject(Long projectId) {
51	        return jdbc.query(
52	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE project_id = ? ORDER BY id ASC",
53	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
54	                        rs.getBigDecimal("amount"), rs.getString("status"),
55	                        rs.getDate("issued_date").toLocalDate().toString(),
56	                        rs.getDate("due_date").toLocalDate().toString()),
57	                projectId);
58	    }
59	
60	    @Transactional(readOnly = true)
61	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
62	        return jdbc.query(
63	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE project_id = ? ORDER BY due_date ASC, id ASC",
64	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
65	                        rs.getBigDecimal("amount"), rs.getString("status"),
66	                        rs.getDate("issued_date").toLocalDate().toString(),
67	                        rs.getDate("due_date").toLocalDate().toString()),
68	                projectId);
69	    }
70	
71	    @Transactional
72	    public InvoiceView create(Long projectId, BigDecimal amount) {
73	        if (projectId == null) {
74	            throw new IllegalArgumentException("An invoice requires a project");
75	        }
76	        if (amount == null) {
77	            throw new IllegalArgumentException("An invoice requires an amount");
78	        }
79	        if (amount.signum() <= 0) {
80	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
81	        }
82	        Invoice invoice = new Invoice();
83	        invoice.setProjectId(projectId);
84	        invoice.setAmount(amount);
85	        // A new invoice goes out today and is due 30 days later.
86	        LocalDate issued = LocalDate.now();
87	        invoice.setIssuedDate(issued);
88	        invoice.setDueDate(issued.plusDays(30));
89	        Invoice saved = repository.save(invoice);
90	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
91	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString());
92	    }
93	
94	    @Transactional
95	    public InvoiceView send(Long invoiceId) {
96	        if (invoiceId == null) {
97	            throw new IllegalArgumentException("An invoice id is required");
98	        }
99	        InvoiceView current = find(invoiceId);
100	        if (!"DRAFT".equals(current.getStatus())) {
101	            throw new IllegalStateException("Only a draft invoice can be sent");
102	        }
103	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
104	        InvoiceView invoice = find(invoiceId);
105	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
106	                + invoice.getAmount().setScale(2));
107	        return invoice;
108	    }
109	
110	    @Transactional
111	    public InvoiceView pay(Long invoiceId) {
112	        if (invoiceId == null) {
113	            throw new IllegalArgumentException("An invoice id is required");
114	        }
115	        InvoiceView current = find(invoiceId);
116	        // Payment is only allowed once an invoice has been sent.
117	        if (!"SENT".equals(current.getStatus())) {
118	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
119	        }
120	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
121	        InvoiceView invoice = find(invoiceId);
122	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
123	                + invoice.getAmount().setScale(2));
124	        return invoice;
125	    }
126	
127	    /** The line items of an invoice, in the order they were added. */
128	    @Transactional(readOnly = true)
129	    public List<LineItemView> listLineItems(Long invoiceId) {
130	        return jdbc.query(
131	                "SELECT id, invoice_id, description, qty, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
132	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
133	                        rs.getString("description"), rs.getInt("qty"),
134	                        rs.getBigDecimal("unit_price")),
135	                invoiceId);
136	    }
137	
138	    /**
139	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
140	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
141	     */
142	    @Transactional
143	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
144	        if (invoiceId == null) {
145	            throw new IllegalArgumentException("An invoice id is required");
146	        }
147	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
148	            throw new IllegalArgumentException("A line item requires a description");
149	        }
150	        if (body.getQty() == null || body.getQty() <= 0) {
151	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
152	        }
153	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
154	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
155	        }
156	        LineItem lineItem = new LineItem();
157	        lineItem.setInvoiceId(invoiceId);
158	        lineItem.setDescription(body.getDescription());
159	        lineItem.setQty(body.getQty());
160	        lineItem.setUnitPrice(body.getUnitPrice());
161	        lineItemRepository.save(lineItem);
162	        jdbc.update(
163	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
164	                invoiceId, invoiceId);
165	        return listLineItems(invoiceId);
166	    }
167	
168	    /**
169	     * Remove one line item from an invoice, then re-derive the invoice's amount as the sum of each
170	     * remaining line's quantity times unit price so the stored total stays in step. Returns the
171	     * invoice's remaining line items.
172	     */
173	    @Transactional
174	    public List<LineItemView> removeLineItem(Long invoiceId, Long lineItemId) {
175	        if (invoiceId == null) {
176	            throw new IllegalArgumentException("An invoice id is required");
177	        }
178	        if (lineItemId == null) {
179	            throw new IllegalArgumentException("A line item id is required");
180	        }
181	        jdbc.update("DELETE FROM line_items WHERE id = ? AND invoice_id = ?", lineItemId, invoiceId);
182	        jdbc.update(
183	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
184	                invoiceId, invoiceId);
185	        return listLineItems(invoiceId);
186	    }
187	
188	    /** The payments a client has made on an invoice, in the order they were recorded. */
189	    @Transactional(readOnly = true)
190	    public List<PaymentView> listPayments(Long invoiceId) {
191	        return jdbc.query(
192	                "SELECT id, invoice_id, amount, paid_date FROM payments WHERE invoice_id = ? ORDER BY id ASC",
193	                (rs, i) -> new PaymentView(rs.getLong("id"), rs.getLong("invoice_id"),
194	                        rs.getBigDecimal("amount"), rs.getDate("paid_date").toLocalDate().toString()),
195	                invoiceId);
196	    }
197	
198	    /** Record one payment a client has made against an invoice. Returns the invoice's payments. */
199	    @Transactional
200	    public List<PaymentView> addPayment(Long invoiceId, NewPayment body) {
201	        if (invoiceId == null) {
202	            throw new IllegalArgumentException("An invoice id is required");
203	        }
204	        if (body == null || body.getAmount() == null || body.getAmount().signum() <= 0) {
205	            throw new IllegalArgumentException("A payment requires an amount greater than zero");
206	        }
207	        if (body.getDate() == null || body.getDate().isBlank()) {
208	            throw new IllegalArgumentException("A payment requires a date");
209	        }
210	        Payment payment = new Payment();
211	        payment.setInvoiceId(invoiceId);
212	        payment.setAmount(body.getAmount());
213	        payment.setPaidDate(LocalDate.parse(body.getDate()));
214	        paymentRepository.save(payment);
215	        audit.record("PAYMENT_RECORDED invoice=" + invoiceId + " amount="
216	                + body.getAmount().setScale(2) + " date=" + body.getDate());
217	        return listPayments(invoiceId);
218	    }
219	
220	    private InvoiceView find(Long invoiceId) {
221	        return jdbc.queryForObject(
222	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE id = ?",
223	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
224	                        rs.getBigDecimal("amount"), rs.getString("status"),
225	                        rs.getDate("issued_date").toLocalDate().toString(),
226	                        rs.getDate("due_date").toLocalDate().toString()),
227	                invoiceId);
228	    }
229	}
