        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
        InvoiceView invoice = find(invoiceId);
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
                + invoice.getAmount().setScale(2));
